package com.alsafa.native4.core;

import android.content.ContentValues;import android.database.Cursor;import android.database.sqlite.SQLiteDatabase;import java.util.ArrayList;import java.util.List;import java.util.UUID;
/** Holds parts for an open repair without creating cash, revenue or profit. Stock is reduced only when consumed at completion. */
public final class RepairPartReservationStore {
 private final CoreStore.DbProvider provider;public RepairPartReservationStore(CoreStore.DbProvider provider){this.provider=provider;}
 public static final class Request{public final String partId;public final int quantity;public Request(String partId,int quantity){this.partId=req(partId,"قطعة الصيانة");if(quantity<=0)throw new IllegalArgumentException("الكمية يجب أن تكون أكبر من صفر");this.quantity=quantity;}}
 public String reserve(String repairId,String partId,int quantity){List<Request> one=new ArrayList<>();one.add(new Request(partId,quantity));return reserveAll(repairId,one).get(0);}
 public List<String> reserveAll(String repairId,List<Request> requests){String r=req(repairId,"معرف الصيانة");if(requests==null||requests.isEmpty())throw new IllegalArgumentException("اختر قطعة صيانة واحدة على الأقل");SQLiteDatabase db=provider.db();db.beginTransaction();try{java.util.LinkedHashMap<String,Integer> totals=new java.util.LinkedHashMap<>();for(Request x:requests){Integer old=totals.get(x.partId);totals.put(x.partId,(old==null?0:old)+x.quantity);}for(java.util.Map.Entry<String,Integer> e:totals.entrySet()){int stock=stock(db,e.getKey()),other=reservedByOthers(db,e.getKey(),r);if(stock-other<e.getValue())throw new IllegalArgumentException("الرصيد المتاح غير كافٍ للقطعة "+e.getKey()+"؛ المتاح بعد الحجوزات: "+Math.max(0,stock-other));}long now=System.currentTimeMillis();ArrayList<String> ids=new ArrayList<>();for(java.util.Map.Entry<String,Integer> e:totals.entrySet()){String id;try(Cursor c=db.rawQuery("SELECT id FROM repair_part_reservations WHERE repair_id=? AND part_id=?",new String[]{r,e.getKey()})){id=c.moveToFirst()?c.getString(0):"rpr-"+UUID.randomUUID();}ContentValues v=new ContentValues();v.put("id",id);v.put("repair_id",r);v.put("part_id",e.getKey());v.put("quantity",e.getValue());v.put("state","RESERVED");v.put("created_at",now);v.putNull("consumed_at");v.putNull("released_at");db.insertWithOnConflict("repair_part_reservations",null,v,SQLiteDatabase.CONFLICT_REPLACE);ids.add(id);}db.setTransactionSuccessful();return ids;}finally{db.endTransaction();}}
 public void consumeAll(String repairId)throws Exception{String r=req(repairId,"معرف الصيانة");SQLiteDatabase db=provider.db();db.beginTransaction();try{List<Row> rows=rows(db,r,"RESERVED");long now=System.currentTimeMillis();for(Row x:rows){int before=stock(db,x.partId),after=before-x.quantity;if(after<0)throw new IllegalStateException("رصيد قطعة الصيانة غير كافٍ عند التسليم: "+x.partId);ContentValues iv=new ContentValues();iv.put("quantity",after);iv.put("updated_at",now);if(db.update("repair_inventory",iv,"part_id=? AND deleted_at IS NULL",new String[]{x.partId})!=1)throw new IllegalArgumentException("قطعة الصيانة غير موجودة: "+x.partId);ContentValues mv=new ContentValues();mv.put("move_id","partmove-"+UUID.randomUUID());mv.put("part_id",x.partId);mv.put("source_type","REPAIR_CONSUME");mv.put("source_id",r);mv.put("before_qty",before);mv.put("delta_qty",-x.quantity);mv.put("after_qty",after);mv.put("created_at",now);db.insertOrThrow("repair_inventory_moves",null,mv);ContentValues rv=new ContentValues();rv.put("state","CONSUMED");rv.put("consumed_at",now);db.update("repair_part_reservations",rv,"id=? AND state='RESERVED'",new String[]{x.id});}db.setTransactionSuccessful();}finally{db.endTransaction();}}
 public void releaseAll(String repairId){String r=req(repairId,"معرف الصيانة");SQLiteDatabase db=provider.db();ContentValues v=new ContentValues();v.put("state","RELEASED");v.put("released_at",System.currentTimeMillis());db.update("repair_part_reservations",v,"repair_id=? AND state='RESERVED'",new String[]{r});}
 public int available(String partId){SQLiteDatabase db=provider.db();return Math.max(0,stock(db,req(partId,"قطعة الصيانة"))-reservedByOthers(db,partId,""));}
 private static int stock(SQLiteDatabase db,String p){try(Cursor c=db.rawQuery("SELECT quantity FROM repair_inventory WHERE part_id=? AND deleted_at IS NULL",new String[]{p})){if(!c.moveToFirst())throw new IllegalArgumentException("قطعة الصيانة غير موجودة");return c.getInt(0);}}
 private static int reservedByOthers(SQLiteDatabase db,String p,String repair){try(Cursor c=db.rawQuery("SELECT COALESCE(SUM(quantity),0) FROM repair_part_reservations WHERE part_id=? AND state='RESERVED' AND repair_id<>?",new String[]{p,repair})){c.moveToFirst();return c.getInt(0);}}
 private static List<Row> rows(SQLiteDatabase db,String r,String state){ArrayList<Row> out=new ArrayList<>();try(Cursor c=db.rawQuery("SELECT id,part_id,quantity FROM repair_part_reservations WHERE repair_id=? AND state=?",new String[]{r,state})){while(c.moveToNext())out.add(new Row(c.getString(0),c.getString(1),c.getInt(2)));}return out;}
 private static String req(String v,String label){String s=v==null?"":v.trim();if(s.isEmpty())throw new IllegalArgumentException(label+" مطلوب");return s;}private static final class Row{final String id,partId;final int quantity;Row(String i,String p,int q){id=i;partId=p;quantity=q;}}
}
